  const out = new Set();
  for (const raw of trimmed.split(',')) {
    const token = raw.trim();
    if (token === '') throw new Error('parseRange: empty token');

    const m = /^(\d+)\s*(?:-\s*(\d+))?$/.exec(token);
    if (!m) throw new Error(`parseRange: malformed token "${token}"`);

    const a = Number(m[1]);
